Context('Numeric');

$image_1 = createLaTeXImage();
$image_1->addToPreamble(latexImagePreamble());
$image_1->BEGIN_LATEX_IMAGE
								\def\vo{node[circle, color=black, fill=white, inner sep=2pt, minimum size = 17pt, draw]{}}
\begin{tikzpicture}[xscale=2]
								\foreach \x in {0,...,4}{
									\coordinate (l\x) at (0,\x);
									\coordinate (r\x) at (2,\x);
								}
								\foreach \x in {0,...,4}{
									\draw[very thick] (l\x) -- (r0) (l\x) -- (r2) (l\x) -- (r4);
									\draw (l\x) \vo;
								}
								\draw (r0) \vo (r2) \vo (r4) \vo;
								\end{tikzpicture}

END_LATEX_IMAGE

############################################################
# Body
############################################################

BEGIN_PGML
>> [@image(insertGraph($image_1), width=>600, alt=>qq"a bipartite graph with 5 vertices on the left each connected to each of 3 vertices on the right")@]*  <<

[`\chi(G) = `] [_]{2}{5}

END_PGML

